-- Rename regions so no two in a city share a name (#5252). Written against evolution 374 (v11.11.0); applied on
-- prod 2026-09-09.
--
-- In Taiwan every village (里) gets its district as a prefix (板橋區中山里), duplicated or not, since a picker with
-- only some names prefixed is worse than either. Elsewhere only duplicated names change, getting the borough after
-- a comma in CDMX (La Joya, Tlalpan) or a hand-picked qualifier like "(East)".
--
-- RUN THE TWO 5252-delete-* SCRIPTS FIRST: the Taiwan names here were picked after those deletions.
--
-- Run on these cities only:
--     scp tools/one-off/5252-rename-regions.sql saugstad@makelab1.cs.washington.edu:sidewalk-server-tools/current-query.sql
--     ./run-query-in-every-city.sh -p -m -c "cdmx chicago detroit kaohsiung keelung new_taipei pittsburgh seattle taichung tainan taipei tucson" -o "5252-renames-applied"
--     scp saugstad@makelab1.cs.washington.edu:sidewalk-server-tools/5252-renames-applied.csv scratchpad/
-- Expect 3963 rows; fewer means regions changed since the list was built. A rename applies only if the region's
-- schema, id and old name still match, so rerunning is safe; it does nothing.
--
-- These names are public: 2908 of the renamed regions are open, holding 239,833 labels. API calls that filter by an
-- old region name return nothing after this.
--
-- The runner sets the search_path.
