applied AS (
  UPDATE region
  SET name = renames.new_name
  FROM renames
  WHERE renames.schema_name = current_schema()
    AND renames.region_id = region.region_id
    AND renames.old_name = region.name
  RETURNING region.region_id, renames.old_name, region.name AS new_name
)
SELECT :'city' AS city, region_id, old_name, new_name FROM applied ORDER BY region_id;
